#include<iostream>
#include<vector>
#include<sstream>
#include<cmath>
#include<algorithm> // Added for std::fill

using namespace std;

const int MAX = 13;
vector<double> Cake;
double box;
double dp[(1<<MAX)][MAX];

void init(){
    Cake.clear();
    // Initialize the dp array with a more efficient method
    for(auto& row : dp) {
        std::fill(std::begin(row), std::end(row), 1e9); // Use 1e9 for readability and performance
    }
    dp[0][0] = 0;
}

void make(){
    string s;
    getline(cin,s);
    stringstream ss(s);
    double num;
    while(ss >> num) Cake.push_back(num);
}

void solve(){
    for(int i = 0; i < (1<<Cake.size()); i++)
        for(int j = 0; j < (int)Cake.size(); j++){
            if(i == 0) {dp[(1<<j)][j] = Cake[j]; continue;}
            for(int k = 0; k < (int)Cake.size(); k++)
                if(!(i&(1<<k)) && j != k){
                    dp[i+(1<<k)][k] = min(dp[i+(1<<k)][k],dp[i][j]+2.0*sqrt(Cake[j]*Cake[k]));
                }
        }

    for(int i = 0; i < (int)Cake.size(); i++){
        if(dp[(1<<Cake.size())-1][i]+Cake[i] <= box) {cout << "OK" << endl;return;}
    }
    cout << "NA" << endl;
}

int main(){
    while(cin >> box){
        init();
        make();
        solve();
    }
    return 0;
}

#include<iostream>
#include<vector>
#include<sstream>
#include<cmath>
#include<algorithm>

using namespace std;

const int MAX = 13;
vector<float> Cake; // Keeping float for optimization
float box;
float dp[(1<<MAX)][MAX];

void init(){
    Cake.clear();
    std::fill(&dp[0][0], &dp[0][0] + (1<<MAX)*MAX, 100000000);
    dp[0][0] = 0;
}

void make(){
    string s;
    getline(cin,s);
    stringstream ss(s);
    float num;
    Cake.reserve(MAX);
    while(ss >> num) Cake.push_back(num);
}

void solve(){
    int n = (int)Cake.size();
    for(int i = 0; i < (1 << n); i++)
        for(int j = 0; j < n; j++){
            if(i == 0) {
                dp[(1<<j)][j] = Cake[j];
                continue;
            }
            if (dp[i][j] == 100000000) continue; // Skip impossible states
            for(int k = 0; k < n; k++)
                if(!(i & (1 << k)) && j != k){
                    float newValue = dp[i][j] + 2.0f * sqrt(Cake[j] * Cake[k]);
                    dp[i | (1 << k)][k] = min(dp[i | (1 << k)][k], newValue);
                }
        }

    for(int i = 0; i < n; i++){
        if(dp[(1 << n) - 1][i] + Cake[i] <= box) {cout << "OK" << endl; return;}
    }
    cout << "NA" << endl;
}

int main(){
    while(cin >> box){
        init();
        make();
        solve();
    }
    return 0;
}

